package com.campusnova.config;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties(prefix="campusnova.ai") public class AiProperties { private boolean enabled=false; private String modelId=""; private String region=""; private String knowledgeBaseId=""; private String guardrailId=""; private String guardrailVersion=""; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getModelId(){return modelId;} public void setModelId(String v){modelId=v;} public String getRegion(){return region;} public void setRegion(String v){region=v;} public String getKnowledgeBaseId(){return knowledgeBaseId;} public void setKnowledgeBaseId(String v){knowledgeBaseId=v;} public String getGuardrailId(){return guardrailId;} public void setGuardrailId(String v){guardrailId=v;} public String getGuardrailVersion(){return guardrailVersion;} public void setGuardrailVersion(String v){guardrailVersion=v;} }
